import { useState } from "react";
import { Row } from "@/shared/ui/layout/Row";

export function MenuRow({ on, onClick, children }: { on?: boolean; onClick?: () => void; children: React.ReactNode }) {
  const [hovered, setHovered] = useState(false);
  const bg = on
    ? "color-mix(in oklch, var(--accent), transparent 90%)"
    : hovered ? "var(--bg-elev2)" : "transparent";
  return (
    <Row
      gap={6}
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        padding: "6px 8px",
        borderRadius: 5, background: bg, cursor: "pointer",
        transition: "background 0.08s",
      }}
    >{children}</Row>
  );
}
